Normal 0 21 false false false NL-BE JA AR-SA /* Style Definitions */ table.MsoNormalTable {mso-style-name:"Normale Tabelle"; mso-tstyle-rowband-size:0; mso-tstyle-colband-size:0; mso-style-noshow:yes; mso-style-priority:99; mso-style-parent:""; mso-padding-alt:0in 5.4pt 0in 5.4pt; mso-para-margin-top:0in; mso-para-margin-right:0in; mso-para-margin-bottom:10.0pt; mso-para-margin-left:0in; line-height:115%; mso-pagination:widow-orphan; font-size:11.0pt; font-family:"Arial",sans-serif; mso-ascii-font-family:Arial; mso-ascii-theme-font:minor-latin; mso-hansi-font-family:Arial; mso-hansi-theme-font:minor-latin; mso-bidi-font-family:Arial; mso-bidi-theme-font:minor-bidi; mso-ansi-language:NL-BE; mso-fareast-language:EN-US;} Normal 0 false false false NL-BE JA AR-SA /* Style Definitions */ table.MsoNormalTable {mso-style-name:"Table Normal"; mso-tstyle-rowband-size:0; mso-tstyle-colband-size:0; mso-style-noshow:yes; mso-style-priority:99; mso-style-parent:""; mso-padding-alt:0cm 5.4pt 0cm 5.4pt; mso-para-margin-top:0cm; mso-para-margin-right:0cm; mso-para-margin-bottom:10.0pt; mso-para-margin-left:0cm; line-height:115%; mso-pagination:widow-orphan; font-size:11.0pt; font-family:"Arial",sans-serif; mso-ascii-font-family:Arial; mso-ascii-theme-font:minor-latin; mso-hansi-font-family:Arial; mso-hansi-theme-font:minor-latin; mso-bidi-font-family:Arial; mso-bidi-theme-font:minor-bidi; mso-ansi-language:NL-BE;} This project aims at improving the Cuban expertise and technological capacity in the fields of protein conjugation and antigen/adjuvant co-formulation by specialized training and expertise transfer from Flemish academics to Cuban scholars and investigators. By teaming up the existing infrastructure and human resources at the Cuban partner (University of Havana) in terms of vaccine development with the expertise of the Flemish partner (Ghent University) in advanced technologies for modification and characterization of biomolecules, we will build a strong collaborative framework for the development of improved, affordable and efficacious vaccine technologies and formulations. As modern protein vaccines frequently make use of sophisticated conjugation technologies, international cooperation is currently required to succeed in establishing an improved vaccination technology platform that will benefit not only Cuba but also the surrounding regions. Normal 0 21 false false false NL-BE X-NONE X-NONE /* Style Definitions */ table.MsoNormalTable {mso-style-name:"Normale Tabelle"; mso-tstyle-rowband-size:0; mso-tstyle-colband-size:0; mso-style-noshow:yes; mso-style-priority:99; mso-style-parent:""; mso-padding-alt:0in 5.4pt 0in 5.4pt; mso-para-margin-top:0in; mso-para-margin-right:0in; mso-para-margin-bottom:10.0pt; mso-para-margin-left:0in; line-height:115%; mso-pagination:widow-orphan; font-size:11.0pt; font-family:"Arial",sans-serif; mso-ascii-font-family:Arial; mso-ascii-theme-font:minor-latin; mso-hansi-font-family:Arial; mso-hansi-theme-font:minor-latin; mso-bidi-font-family:"Times New Roman"; mso-bidi-theme-font:minor-bidi; mso-ansi-language:NL-BE; mso-fareast-language:EN-US;}
